import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const root=path.dirname(fileURLToPath(import.meta.url)),batchFile=process.argv[2];
const plan=JSON.parse(fs.readFileSync(path.join(root,'plan.json'),'utf8'));
function batch(){return JSON.parse(fs.readFileSync(batchFile,'utf8'));}
function call(file,args){return new Promise((resolve,reject)=>{const child=spawn(process.execPath,[path.join(root,file),...args],{stdio:['ignore','pipe','pipe'],shell:false,windowsHide:true});child.stdout.on('data',s=>process.stdout.write(s));child.stderr.on('data',s=>process.stderr.write(s));child.on('error',reject);child.on('close',code=>code===0?resolve():reject(new Error(`controller exited ${code}; no retry`)));});}
for(const id of Object.keys(batch().cases)){
  let state=batch().cases[id];
  if(!state.attempts.length) await call('harness.mjs',['start','--batch',batchFile,'--variant',id]);
  while(true){
    state=batch().cases[id]; const attempt=state.attempts.at(-1),count=attempt.turns.length;
    if(attempt.turns.at(-1)?.transportStatus!=='COMPLETE')throw new Error(`transport incomplete ${id}; preserve attempt and stop`);
    if(count===state.plannedTurns)break;
    const script=plan.variants.find(v=>v.id===id).turns[count];
    if(script.includes('{label}')&&!attempt.selection)await call('choose-first.mjs',[batchFile,id]);
    await call('harness.mjs',['next','--batch',batchFile,'--variant',id]);
  }
  process.stdout.write(JSON.stringify({variantComplete:id,semanticStatus:'UNKNOWN_PENDING_INDEPENDENT_REVIEW'})+'\n');
  await call('record-native-loading.mjs',[batchFile]);
}
await call('harness.mjs',['inspect','--batch',batchFile]);
await call('operator-observations.mjs',[batchFile]);

